"""All translated UI strings (STRINGS), and the supported-language
ordering/native-name lookups used by the language picker."""

from typing import Dict, List, Tuple


# Supported UI languages: code -> name written in that language itself
# (NOT translated depending on the active UI language - e.g. "Deutsch"
# always reads "Deutsch", regardless of whether the app is currently in
# Hungarian or Spanish). Used both for the Options -> Appearance language
# dropdown and the first-run language picker. LANGUAGE_ORDER is derived
# automatically, sorted alphabetically by that native name - see product
# requirement "language list is alphabetical, in each language's own
# name". English is the default/fallback language everywhere in the app.
LANGUAGE_NATIVE_NAMES: Dict[str, str] = {
    "de": "Deutsch",
    "en": "English",
    "es": "Español",
    "fr": "Français",
    "hu": "Magyar",
    "pl": "Polski",
    "pt_br": "Português (Brasil)",
    "ru": "Русский",
    "uk": "Українська",
}
LANGUAGE_ORDER: List[str] = sorted(LANGUAGE_NATIVE_NAMES, key=lambda code: LANGUAGE_NATIVE_NAMES[code])
# Languages added via AI translation (everything except the two originally
# hand-written languages) - used to show an "AI-translated" hint next to
# the language picker, see section_language in the Appearance tab.
AI_TRANSLATED_LANGUAGES: Tuple[str, ...] = ("de", "fr", "ru", "pl", "pt_br", "es", "uk")

# UI strings for every supported language (see LANGUAGE_ORDER). Keys are
# shared across all languages - see App._() for lookup with English
# fallback. "hu" and "en" were hand-written; the rest were produced with
# AI assistance and are flagged to the user via ai_translation_note (see
# AI_TRANSLATED_LANGUAGES above and the Appearance settings tab).
